#!/usr/bin/env python3
"""TRACK-D: freeze the 6 memorization-probe paraphrases into candidates.json.

One fixed pass per instance, written AFTER the R7 GO and BEFORE any judge
scoring. Each paraphrase rewords the truth passage's meaning in fresh
French prose (natural spacing/punctuation), comparable length to the
truth decode. Frozen with sha256; blind 8-hex labels added; label_map.json
updated (still sealed until all 54 queries are logged).
"""
import hashlib
import json
import os
import random

HERE = os.path.dirname(os.path.abspath(__file__))

PARAPHRASES = {
'184101': """En 1815, Charles-François-Bienvenu Myriel, âgé d'environ soixante-quinze ans, occupait depuis 1806 le siège épiscopal de Digne. Sur son passé circulaient toutes sortes de rumeurs, fondées ou non, car les propos que l'on tient sur un homme pèsent souvent aussi lourd dans sa destinée que ses actes. Fils d'un conseiller au parlement d'Aix, issu de la noblesse de robe, on l'avait marié très jeune pour lui transmettre la charge paternelle. Malgré ce mariage, le jeune Charles Myriel, bien fait, élégant et spirituel, avait beaucoup défrayé la chronique mondaine. Puis la Révolution éclata, dispersant les familles parlementaires. Il émigra en Italie dès les premiers jours ; son épouse y succomba à une maladie de poitrine, et ils n'eurent pas d'enfants. Nul ne sut ce qui transforma alors sa destinée — l'effondrement de l'ancien monde, la ruine des siens, les spectacles tragiques de 93 vus de loin — mais lorsqu'il revint d'Italie, il était prêtre. En 1804, on le trouve curé de Brignolles, déjà vieux, vivant retiré. Une affaire de sa paroisse l'amena à Paris vers l'époque du couronnement, où il sollicitait le cardinal Fesch. Attendant dans une antichambre, il croisa Napoléon qui, intrigué par le regard du vieillard, demanda brusquement qui était ce bonhomme. « Sire, répondit Myriel, vous regardez un bonhomme, et moi je regarde un grand homme ; chacun de nous peut profiter. » Le soir même, l'empereur s'enquit de ce curé, et peu après Myriel apprit avec surprise sa nomination à l'évêché de Digne. Il s'installa avec sa soeur, mademoiselle Baptistine, de dix ans sa cadette, et leur unique domestique, madame Magloire, jadis servante de M. le curé, devenue femme de chambre et femme de charge. Le palais épiscopal, attenant à l'hôpital, était un vaste hôtel seigneurial aux jardins magnifiques. L'évêque y mena une existence d'une simplicité extrême. Ayant réclamé les trois mille francs annuels votés pour ses frais de carrosse et de tournées, il en dressa aussitôt la répartition : bouillon pour les malades de l'hôpital, sociétés de charité maternelle, enfants trouvés, orphelins — la totalité reversée. Un sénateur de l'empire s'en indigna par écrit auprès du ministre des cultes, dénonçant le luxe des prêtres. Les pauvres du pays, eux, avaient choisi dans ses prénoms celui qui avait un sens et ne l'appelaient que monseigneur Bienvenu, nom qui lui plaisait : « Bienvenu corrige monseigneur », disait-il.""",

'184102': """Les paroles de l'évêque valaient ses actes, et ses actes valaient ses paroles. Un jour, trop petit pour atteindre un livre placé trop haut dans sa bibliothèque, il demanda une chaise à madame Magloire : « Ma grandeur ne va pas jusqu'à cette planche. » Sa cousine, la comtesse de Lô, énumérait complaisamment les « espérances » de ses trois fils — héritages, duché, pairie — quand l'évêque, rêveur, l'interrompit : « Je songe à quelque chose de singulier, dans saint Augustin : Mettez votre espérance dans celui auquel on ne succède point. » Recevant un faire-part funèbre chargé de titres nobiliaires, il s'écria : « Quel bon dos a la mort ! » Un jeune vicaire ayant prêché sur la charité, un riche manufacturier usurier, M. Géborand, qui de sa vie n'avait fait l'aumône, se mit à donner chaque dimanche un sou aux mendiantes du portail. L'évêque, le voyant, dit en souriant à sa soeur : « Voilà monsieur Géborand qui achète pour un sou de paradis. » Quêtant dans un salon, il aborda le marquis de Champtercier, avare et voltairien : « Monsieur le marquis, il faut que vous me donniez quelque chose. — Monseigneur, j'ai mes pauvres. — Donnez-les-moi, » répondit l'évêque. Dans un sermon resté célèbre, il dénonça l'impôt des portes et fenêtres qui entassait les paysans dans des masures sans air, et décrivit la misère du Dauphiné : pas de brouettes, pas de chandelles, le pain cuit pour six mois avec de la bouse séchée. Né Provençal, il parlait tous les patois du Midi, ce qui lui ouvrait toutes les âmes. Se qualifiant lui-même d'ex-pécheur, il professait une doctrine d'indulgence : l'homme traîne sa chair et lui cède ; être saint est l'exception, être juste est la règle ; le péché est une gravitation. Apprenant l'histoire d'un faux-monnayeur perdu par la jalousie qu'un procureur avait savamment attisée chez sa complice, il demanda doucement : « Et où jugera-t-on monsieur le procureur du roi ? » Un condamné à mort, ancien bateleur, se vit refuser l'aumônier de la prison ; l'évêque prit sa place, passa le jour et la nuit auprès du misérable, le suivit en camail violet jusqu'à l'échafaud, l'embrassa avant le couteau : « Celui que l'homme tue, Dieu le ressuscite. » De retour, il dit à sa soeur : « Je viens d'officier pontificalement. » La vue de la guillotine le hanta longtemps ; il en tira une méditation sur cette machine qui n'est pas neutre et ne permet pas de rester neutre. On l'appelait à toute heure au chevet des mourants ; il savait se taire des heures auprès d'un affligé, puis parler pour tourner la douleur vers l'espérance. Sa vie intérieure égalait sa vie publique : une pauvreté volontaire, dont témoignaient ses soutanes qu'il faisait durer trop longtemps.""",

'184103': """La maison de l'évêque, qui avait été l'hôpital avant d'être le parloir des bourgeois, se composait d'un rez-de-chaussée et d'un étage : trois pièces en bas, trois chambres en haut, un grenier, et derrière un jardin d'un quart d'arpent. Les deux femmes logeaient au premier ; l'évêque occupait le bas, avec pour salle à manger la pièce ouvrant sur la rue, pour chambre la deuxième, pour oratoire la troisième, d'où l'on ne sortait qu'en traversant la chambre. L'ancienne pharmacie de l'hôpital était devenue cuisine et cellier ; l'ancienne cuisine, une étable où il entretenait deux vaches dont il envoyait chaque matin la moitié du lait aux malades de l'hôpital : « Je paye ma dîme », disait-il. L'hiver, il se retirait le soir dans un compartiment de planches aménagé dans l'étable, son « salon d'hiver », meublé comme la salle à manger d'une table de bois blanc et de chaises de paille. Un vieux buffet peint en rose, habillé de napperons, lui servait d'autel ; les riches pénitentes qui voulaient lui offrir un autel neuf voyaient chaque fois leur argent donné aux pauvres : « Le plus beau des autels, c'est l'âme d'un malheureux consolé qui remercie Dieu. » Il ne lui restait de son ancienne fortune que six couverts d'argent et une grande cuiller, serrés chaque soir dans un placard dont on n'ôtait jamais la clef, plus deux flambeaux massifs hérités d'une grand'tante. « Je renoncerais difficilement à manger dans de l'argenterie », avouait-il. Dans son jardin en croix, madame Magloire cultivait des légumes sur trois carrés ; le quatrième, réservé aux fleurs, lui valut cette remontrance : « Il vaudrait mieux des salades que des bouquets. — Madame Magloire, vous vous trompez. Le beau est aussi utile que l'utile. Plus peut-être. » Aucune porte de la maison ne fermait à clef ; celle de la salle à manger, jadis verrouillée comme une prison, n'était plus close qu'au loquet, jour et nuit. Aux inquiétudes d'un curé, il répondit en citant le psaume : « Nisi Dominus custodierit domum, in vanum vigilant qui custodiunt eam », et il avait écrit en marge d'une bible : « La porte du prêtre doit toujours être ouverte. » C'est dans cet esprit qu'il faut placer l'aventure de Cravatte. Ce lieutenant de brigands infestait la montagne ; le maire du Chastelar supplia l'évêque, en tournée, de rebrousser chemin ou du moins d'accepter une escorte. « Je compte aller sans escorte... Je ne suis pas en ce monde pour garder ma vie, mais pour garder les âmes. » Il partit avec un seul enfant pour guide, passa quinze jours chez les bergers, et voulut chanter un Te Deum sans ornements pontificaux. On apporta alors une caisse contenant la chape d'or, la mitre et la crosse volées un mois plus tôt à Notre-Dame d'Embrun, avec ce billet : « Cravatte à monseigneur Bienvenu. » Au curé qui murmurait « Dieu, ou le diable », l'évêque répondit avec autorité : « Dieu ! » De retour, il déclara à sa soeur : « Le pauvre prêtre est allé chez ces pauvres montagnards les mains vides, il en revient les mains pleines. » Et le soir : « Ne craignons jamais les voleurs ni les meurtriers... Les préjugés, voilà les voleurs ; les vices, voilà les meurtriers. » Quant au trésor, on trouva dans ses papiers cette note : « La question est de savoir si cela doit faire retour à la cathédrale ou à l'hôpital. » Peu après, à un dîner chez le préfet, le sénateur épicurien dont il a été question, un peu égayé, s'écria : « Parbleu, monsieur l'évêque, causons... J'ai ma philosophie. »""",

'184104': """Pour faire comprendre le ménage intérieur de l'évêque et la manière dont les deux saintes filles pliaient leurs habitudes aux siennes sans qu'il eût à parler, le mieux est de transcrire une lettre de mademoiselle Baptistine à son amie d'enfance, la vicomtesse de Boischevron. En lavant les murs, madame Magloire a fait des découvertes : sous les papiers blanchis à la chaux se cachent d'anciennes peintures — Télémaque reçu chevalier par Minerve, des romains et des romaines — et ma chambre sera bientôt un vrai musée. « Mon frère est si bon. Il donne tout ce qu'il a aux indigents et aux malades. Nous sommes très gênés... Vous voyez que ce sont de grandes douceurs. » La porte de la maison n'est jamais fermée ; entre qui veut. Il ne craint rien, ni la nuit, ni les routes suspectes. L'an dernier, parti seul quinze jours au pays des voleurs malgré nos craintes, il revint bien portant en disant : « Voilà comme on m'a volé ! » et ouvrit une malle pleine des bijoux de la cathédrale d'Embrun que les brigands lui avaient donnés. « À présent j'ai fini par m'y accoutumer... je rentre dans ma chambre, je prie pour lui, et je m'endors... Le diable entrerait dans la maison qu'on le laisserait faire. Après tout... le bon Dieu l'habite. » Suit un long renseignement généalogique sur la famille de Faux, très ancienne noblesse normande, que l'évêque, excellent royaliste et mémorialiste, lui a dicté. Peu après la date de cette lettre, l'évêque fit une chose jugée plus risquée encore que sa promenade chez les bandits. Près de Digne vivait solitaire un ancien conventionnel, nommé G., objet d'horreur dans la petite ville : un quasi-régicide, un athée, disait-on — commérages des oies sur le vautour. N'ayant pas voté la mort du roi, il avait échappé à l'exil et habitait, à trois quarts d'heure de la ville, un repaire perdu dans un vallon sauvage, sans voisins ni passants. L'évêque regardait parfois l'horizon vers ce bouquet d'arbres et disait : « Il y a là une âme qui est seule », ajoutant en lui-même : « Je lui dois ma visite. » Au fond, il partageait l'éloignement général ; la brebis lui semblait bien galeuse pour le pasteur. Mais un jour on apprit que le vieux scélérat se mourait, la paralysie le gagnant. L'évêque prit son bâton, mit son pardessus à cause de sa soutane usée, et partit au soleil déclinant. Il franchit fossé, haie et échalier, et découvrit une cabane basse, indigente et propre, avec une treille à la façade. Devant la porte, un homme aux cheveux blancs souriait au soleil dans une chaise à roulettes, tandis qu'un petit pâtre lui tendait une jatte de lait. « Merci, dit le vieillard, je n'ai plus besoin de rien... Depuis que je suis ici, voilà la première fois qu'on entre chez moi. Qui êtes-vous, monsieur ? — Je me nomme Bienvenu Myriel. » Le conventionnel, qui allait mourir dans trois heures — le froid montait des pieds aux genoux et gagnait la ceinture — renvoya l'enfant se coucher : « Pendant qu'il dormira, je mourrai. » L'évêque, un peu choqué de n'être pas appelé monseigneur, sentit naître en lui une sévérité inaccoutumée devant ce puissant d'autrefois. Le vieillard, lui, gardait tous les gestes de la santé : regard clair, voix vibrante, épaules robustes — chair par en haut, marbre par en bas, comme ce roi du conte oriental.""",

'184105': """Le dialogue du mourant et de l'évêque se poursuivit. « Quant à Louis XVI, j'ai dit non, déclara le conventionnel. Je ne me crois pas le droit de tuer un homme ; mais je me sens le devoir d'exterminer le mal. J'ai voté la fin du tyran, c'est-à-dire la fin de la prostitution pour la femme, la fin de l'esclavage pour l'homme, la fin de la nuit pour l'enfant. En votant la république, j'ai voté la fraternité, la concorde, l'aurore ! » L'évêque murmura : « Oui ? 93 ! » Le vieillard se dressa : « Ah ! vous y voilà ! J'attendais ce mot-là. Un nuage s'est formé pendant quinze cents ans ; au bout de quinze siècles, il a crevé. Vous faites le procès au coup de tonnerre. » L'évêque répondit que le prêtre parle au nom de la pitié, justice plus élevée, et qu'un coup de tonnerre ne doit pas se tromper — puis, fixant le conventionnel : « Louis XVII ? » Le mourant saisit son bras : pleure-t-on l'enfant innocent ou l'enfant royal ? Le frère de Cartouche, pendu en place de Grève pour le seul crime d'être le frère de Cartouche, ne lui semble pas moins douloureux que le petit-fils de Louis XV martyrisé au Temple. « Christ aimait les crudités du vrai, reprit-il ; il ne se fût pas gêné de rapprocher le dauphin de Barabbas du dauphin d'Hérode. L'innocence est aussi auguste déguenillée que fleurdelysée. » L'évêque, à voix basse : « C'est vrai. » Il faut pleurer sur tous les enfants, ceux d'en bas comme ceux d'en haut — « et si la balance doit pencher, que ce soit du côté du peuple. Il y a plus longtemps qu'il souffre. » Puis, explosion : « Qui êtes-vous ? Vous êtes un prince de l'Église, un de ces hommes dorés, rentés, qui roulent carrosse au nom de Jésus-Christ qui allait pieds nus ! Votre nom est arrivé jusqu'à moi, mais les habiles ont tant de manières d'en faire accroire au peuple. » L'évêque baissa la tête : « Vermis sum. — Un ver de terre en carrosse ! » grommela le conventionnel. Doux, l'évêque demanda en quoi son carrosse, sa table et ses vingt-cinq mille livres de rentes prouvaient que la pitié n'est pas une vertu et que 93 fut inexorable. Le vieillard s'excusa de son manque de courtoisie, puis riposta : « Que pensez-vous de Marat battant des mains à la guillotine ? — Que pensez-vous de Bossuet chantant le Te Deum sur les dragonnades ? » Et il aligna les terreurs de la monarchie contre celles de la Révolution : Montrevel, Lamoignon-Bâville, Louvois, et cette huguenote de 1685, liée nue à un poteau, son nourrisson tenu à distance, sommée de choisir entre la mort de son enfant et celle de sa conscience. « La révolution française a eu ses raisons. Les brutalités du progrès s'appellent révolutions. Quand elles sont finies, on reconnaît que le genre humain a été rudoyé, mais qu'il a marché. » L'évêque joua sa dernière carte : « Le progrès doit croire en Dieu. Le bien ne peut pas avoir de serviteur impie. » Le vieillard trembla, une larme coula, et il dit, l'oeil perdu : « O toi ! ô idéal ! toi seul existes ! » Puis, levant un doigt vers le ciel : « L'infini est. Il est là. Si l'infini n'avait pas de moi, le moi serait sa borne ; il ne serait pas infini. Or il est. Donc il a un moi. Ce moi de l'infini, c'est Dieu. » Épuisé, les yeux fermés, il touchait à sa fin. L'évêque prit sa main glacée : « Cette heure est celle de Dieu. Ne trouvez-vous pas regrettable que nous nous fussions rencontrés en vain ? » Le mourant rouvrit les yeux et fit le récit de sa vie : les abus combattus, le territoire défendu, la pauvreté gardée — il dînait à vingt-deux sous rue de l'Arbre-Sec quand les caves du Trésor regorgeaient d'or —, les opprimés secourus, un couvent sauvé en 1793, puis la proscription et l'isolement accepté sans haine. « J'ai quatre-vingt-six ans ; je vais mourir. Qu'est-ce que vous venez me demander ? — Votre bénédiction, » dit l'évêque, et il s'agenouilla. Quand il releva la tête, le conventionnel venait d'expirer, la face devenue auguste. L'évêque rentra absorbé, passa la nuit en prière, et désormais ne répondit aux curieux qu'en montrant le ciel, redoublant de tendresse pour les petits et les souffrants.""",

'184106': """Autour d'un évêque gravite d'ordinaire une escouade de petits abbés, comme autour d'un général une volée de jeunes officiers — ce que saint François de Sales nomme les « prêtres blancs-becs ». Toute puissance a son entourage, toute fortune sa cour ; les chercheurs d'avenir tourbillonnent autour du présent splendide, car l'apostolat ne dédaigne pas le canonicat. Il y a dans l'Église, comme ailleurs, des « grosses mitres » : évêques bien en cour, riches et habiles, traits d'union entre la sacristie et la diplomatie, qui font pleuvoir sur leur suite grasses paroisses et prébendes en attendant les dignités. Leur rayonnement empourpre leur cortège ; c'est tout un système solaire en marche, et Rome est au bout : de la Grandeur à l'Éminence il n'y a qu'un pas, et de l'Éminence à la Sainteté que la fumée d'un scrutin. Monseigneur Bienvenu, humble, pauvre, particulier, n'était pas de ces grosses mitres, et cela se voyait à l'absence complète de jeunes prêtres autour de lui : à peine ordonnés, les séminaristes se faisaient recommander à Aix ou à Auch, car on veut être poussé, et un saint d'une abnégation excessive est un voisinage dangereux — il pourrait communiquer par contagion une pauvreté incurable. De là son isolement, dans une société où réussir est l'enseignement qui tombe goutte à goutte de la corruption : le succès, ce sosie du talent, a pour dupe l'histoire ; « Prospérité suppose Capacité » ; la multitude décerne le génie à quiconque atteint son but, fût-ce un apothicaire inventeur de semelles de carton. Sur sa foi, il n'y a pas à sonder l'évêque de Digne : devant une telle âme, on n'est en humeur que de respect. Jamais ses difficultés de croyance ne se résolvaient en hypocrisie ; il croyait le plus qu'il pouvait — « Credo in Patrem ! » — et puisait dans les bonnes oeuvres cette satisfaction qui dit tout bas : « Tu es avec Dieu. » Mais au-delà de sa foi, il avait un excès d'amour — quia multum amavit — qui le faisait juger vulnérable par les gens raisonnables. Sa bienveillance débordait jusqu'aux choses : il n'avait pas cette dureté irréfléchie que tant de prêtres réservent à l'animal. Les laideurs de l'aspect ne l'indignaient pas ; il semblait y chercher une excuse, comme le linguiste déchiffre un palimpseste. Sa soeur l'entendit un matin, devant une araignée noire et velue : « Pauvre bête ! ce n'est pas sa faute. » Un jour il se donna une entorse pour n'avoir pas voulu écraser une fourmi. Jadis homme passionné, peut-être violent, sa mansuétude était le fruit d'une conviction lentement filtrée dans son coeur, pensée à pensée. À soixante-quinze ans, il n'en paraissait pas soixante : une « belle tête » si aimable qu'on oubliait qu'elle était belle, le rire facile — mais qu'on restât quelques heures près de lui lorsqu'il était pensif, et le bonhomme se transfigurait : la majesté se dégageait de cette bonté sans que la bonté cessât de rayonner, comme un ange souriant qui ouvrirait lentement ses ailes. Prière, offices, aumône, consolation, jardinage, frugalité, étude remplissaient ses journées jusqu'aux bords ; et si le temps le permettait, il passait une heure ou deux dans son jardin avant de dormir, seul avec les constellations, offrant son coeur à l'heure où les fleurs nocturnes offrent leur parfum, ébloui par Dieu plutôt qu'étudiant Dieu, songeant aux infinis qui s'enfonçaient sous ses yeux. « Mystérieux échanges des gouffres de l'âme avec les gouffres de l'univers ! » Que lui fallait-il de plus ? Un petit jardin pour se promener, et l'immensité pour rêver ; quelques fleurs sur la terre et toutes les étoiles dans le ciel.""",
}


def main():
    doc = json.load(open(os.path.join(HERE, 'candidates.json')))
    cands = doc['candidates']
    lmap = json.load(open(os.path.join(HERE, 'label_map.json')))
    rng = random.Random(71007100)  # label draw only
    used = set(cands)
    added = {}
    for seed in sorted(PARAPHRASES):
        text = PARAPHRASES[seed]
        while True:
            lab = '%08x' % rng.randrange(2**32)
            if lab not in used:
                used.add(lab)
                break
        cands[lab] = {
            'text': text,
            'sha256': hashlib.sha256(text.encode()).hexdigest(),
            'len': len(text),
            'frozen_note': 'paraphrase: one fixed operator pass, post-R7-GO, pre-scoring; natural spacing',
        }
        lmap[lab] = {'seed': seed, 'class': 'paraphrase'}
        added[seed] = (lab, cands[lab]['sha256'][:16], len(text))
    doc['meta']['paraphrases_frozen'] = {
        'note': 'written after R7 GO (2026-10-07), before any judge scoring; frozen with sha256',
    }
    json.dump(doc, open(os.path.join(HERE, 'candidates.json'), 'w'), ensure_ascii=False)
    json.dump(lmap, open(os.path.join(HERE, 'label_map.json'), 'w'), indent=1)
    print('paraphrases frozen:')
    for seed, (lab, h, n) in sorted(added.items()):
        print(f'  {seed} -> {lab} sha256:{h} len:{n}')
    print('total candidates:', len(cands))


if __name__ == '__main__':
    main()
